/**
 * Validates dispatch commands against plant safety interlocks.
 */
export function validateDispatchPlan(plan: DispatchCommand): {
  isValid: boolean;
  violations: string[];
} {
  const violations: string[] = [];

  // Interlock 1: BESS C-rate and thermal envelope
  if (plan.batterySetpointMW > 90) {
    violations.push("BESS discharge setpoint breaches 90 MW C-rate inverter safety threshold.");
  }
  if (plan.batterySetpointMW < -80) {
    violations.push("BESS charging setpoint breaches 80 MW fast-charge current safety envelope.");
  }

  // Interlock 2: Grid contract ceiling & reverse power
  if (plan.gridImportSetpointMW > 250) {
    violations.push("Grid import setpoint breaches 250 MW contract demand ceiling.");
  }
  if (plan.gridImportSetpointMW < 0) {
    violations.push(
      "Reverse power protection interlock active: Grid backfeeding prohibited under HT-2 tariff.",
    );
  }

  // Interlock 3: Generator minimum stable load
  if (plan.generatorSetpointMW > 0 && plan.generatorSetpointMW < 12) {
    violations.push("Generator setpoint is below 12 MW technical minimum stable load.");
  }

  // Interlock 4: Captive thermal minimum
  if (plan.captiveSetpointMW < 30) {
    violations.push("Captive thermal generator cannot operate below 30 MW minimum throttle.");
  }

  return {
    isValid: violations.length === 0,
    violations,
  };
}

/**
 * Simulates real-time dispatch execution in the pre-commissioning sandbox.
 * Generates genuine cryptographic SHA-256 audit hashes for every recorded action.
 */
export function simulateDispatchExecution(plan: DispatchCommand): {
  success: boolean;
  auditEntry: AuditLogEntry;
  error?: string;
  isSimulationOnly: true;
} {
  const validation = validateDispatchPlan(plan);
  const now = new Date().toISOString();

  if (!validation.isValid) {
    const errorPayload = `REJECTED|${plan.commandId}|${now}|${plan.authorizedBy}|${validation.violations.join(";")}`;
    const auditEntry: AuditLogEntry = {
      id: `AUD-SIM-${Date.now()}`,
      timestamp: now,
      operatorId: plan.authorizedBy,
      action: "SIMULATION_DISPATCH_REJECTED",
      targetAsset: "Digital Twin Simulation Sandbox",
      newSetpoint: "REJECTED_BY_INTERLOCKS",
      validationStatus: "INTERLOCK_VIOLATION",
      hashSha256: sha256(errorPayload),
      provenance: "Simulation interlock violation caught; no setpoints applied",
    };

    AUDIT_LOG.unshift(auditEntry);
    return {
      success: false,
      auditEntry,
      error: validation.violations.join("; "),
      isSimulationOnly: true,
    };
  }

  // Genuine cryptographic SHA-256 hash over canonical audit tuple
  const canonicalAuditPayload = `${plan.commandId}|${now}|${plan.authorizedBy}|BESS:${plan.batterySetpointMW}|Grid:${plan.gridImportSetpointMW}|Cap:${plan.captiveSetpointMW}|Gen:${plan.generatorSetpointMW}|SIMULATION_ONLY`;
  const cryptographicHash = sha256(canonicalAuditPayload);

  const auditEntry: AuditLogEntry = {
    id: `AUD-SIM-${Date.now()}`,
    timestamp: now,
    operatorId: plan.authorizedBy,
    action: "SIMULATION_DISPATCH_RECORDED",
    targetAsset: "Digital Twin Simulation Sandbox",
    newSetpoint: `BESS:${plan.batterySetpointMW}MW|Grid:${plan.gridImportSetpointMW}MW|Cap:${plan.captiveSetpointMW}MW`,
    validationStatus: "PASSED_SIMULATION_INTERLOCKS",
    hashSha256: cryptographicHash,
    provenance:
      "Digital Twin Sandbox Mode: Field PLC actuation locked pending edge gateway deployment",
  };

  AUDIT_LOG.unshift(auditEntry);
  return { success: true, auditEntry, isSimulationOnly: true };
}

/**
 * Attempt Physical Equipment Actuation.
 *
 * CRITICAL SAFETY GATEKEEPER:
 * This method categorically intercepts and blocks any attempt to actuate physical equipment.
 * Physical actuation is permanently locked until independent site-specific telemetry calibration,
 * protection relays (IEEE 1547 / IEC 61850), hardware trapped-key permissives, and plant safety SOPs
 * have been verified and certified.
 */
export function attemptPhysicalActuation(plan: DispatchCommand): {
  success: false;
  actuationBlocked: true;
  errorCode: "ERR_PHYSICAL_ACTUATION_LOCKED_PENDING_SITE_VALIDATION";
  message: string;
  auditEntry: AuditLogEntry;
} {
  const now = new Date().toISOString();
  const errorPayload = `BLOCKED_PHYSICAL_ACTUATION|${plan.commandId}|${now}|${plan.authorizedBy}|SITE_SAFETY_VALIDATION_INCOMPLETE`;
  const cryptographicHash = sha256(errorPayload);

  const auditEntry: AuditLogEntry = {
    id: `AUD-ACT-LOCK-${Date.now()}`,
    timestamp: now,
    operatorId: plan.authorizedBy,
    action: "PHYSICAL_ACTUATION_BLOCKED",
    targetAsset: "Physical Switchyard & Generator Governors",
    newSetpoint: "ACTUATION_PERMANENTLY_LOCKED",
    validationStatus: "REJECTED",
    hashSha256: cryptographicHash,
    provenance:
      "HARDWARE LOCKOUT ACTIVE: Physical equipment actuation rejected pending independent site validation",
  };

  AUDIT_LOG.unshift(auditEntry);

  return {
    success: false,
    actuationBlocked: true,
    errorCode: "ERR_PHYSICAL_ACTUATION_LOCKED_PENDING_SITE_VALIDATION",
    message:
      "PHYSICAL EQUIPMENT ACTUATION REJECTED: All closed-loop physical actuation pathways are locked at the architecture level. Operating strictly in Digital Twin Simulation sandbox mode. Independent telemetry calibration, protection interlocks (IEC 61850), and operational safety sign-offs remain pending.",
    auditEntry,
  };
}

import { z } from "zod";

/**
 * Strict Runtime Zod Command Validation Schema
 * Enforces rigorous type, range, and format contracts between the LP Optimizer output
 * and the SCADA equipment dispatch emitter.
 */
export const ScadaDispatchSetpointsSchema = z.object({
  solarCurtailmentMW: z.number().min(0).max(200),
  windCurtailmentMW: z.number().min(0).max(150),
  bessDischargeMW: z.number().min(0).max(90),
  bessChargeMW: z.number().min(0).max(80),
  gridContractMW: z.number().min(0).max(250),
  gridExcessMW: z.number().min(0).max(50),
  captiveMW: z.number().min(30).max(95),
  generatorMW: z.number().min(0).max(120),
  generatorCommitted: z.boolean(),
});

export type ScadaSetpoints = z.infer<typeof ScadaDispatchSetpointsSchema>;

export const ScadaDispatchCommandSchema = z.object({
  commandId: z.string().min(5),
  timestamp: z.string().min(10),
  heartbeatTimestampMs: z.number().int().positive(),
  source: z.literal("LP_OPTIMIZATION_ENGINE"),
  setpoints: ScadaDispatchSetpointsSchema,
  operatorAuthorization: z.object({
    authorized: z.boolean(),
    operatorId: z.string().min(1),
    signature: z.string().min(16),
  }),
});

export type ScadaDispatchCommand = z.infer<typeof ScadaDispatchCommandSchema>;

/**
 * Deadband Filter (0.5 kW / 0.0005 MW threshold)
 * Prevents actuator chatter, excessive PLC register writes, and switchgear mechanical wear
 * by suppressing setpoint changes smaller than the deadband limit.
 */
export const SCADA_DEADBAND_THRESHOLD_MW = 0.0005; // 0.5 kW

export function applyDeadbandFilter(
  newSetpoints: ScadaSetpoints,
  currentSetpoints: ScadaSetpoints,
  deadbandThresholdMW = SCADA_DEADBAND_THRESHOLD_MW,
): { filteredSetpoints: ScadaSetpoints; suppressedAssets: string[]; modifiedAssets: string[] } {
  const filtered = { ...newSetpoints };
  const suppressedAssets: string[] = [];
  const modifiedAssets: string[] = [];

  const checkKeys: (keyof Omit<ScadaSetpoints, "generatorCommitted">)[] = [
    "solarCurtailmentMW",
    "windCurtailmentMW",
    "bessDischargeMW",
    "bessChargeMW",
    "gridContractMW",
    "gridExcessMW",
    "captiveMW",
    "generatorMW",
  ];

  for (const key of checkKeys) {
    const delta = Math.abs(newSetpoints[key] - currentSetpoints[key]);
    if (delta > 0 && delta < deadbandThresholdMW) {
      filtered[key] = currentSetpoints[key]; // Suppress jitter
      suppressedAssets.push(
        `${key} (delta: ${(delta * 1000).toFixed(2)} kW < ${(deadbandThresholdMW * 1000).toFixed(1)} kW)`,
      );
    } else if (delta >= deadbandThresholdMW) {
      modifiedAssets.push(key);
    }
  }

  return { filteredSetpoints: filtered, suppressedAssets, modifiedAssets };
}

/**
 * Software Watchdog & Stale Telemetry Fail-Safe Demarcation
 * Monitors heartbeat freshness. If telemetry is older than 10 seconds,
 * automated dispatch is strictly locked out and a high-priority operator alarm is raised.
 */
export class ScadaWatchdogMonitor {
  private lastHeartbeatMs: number = Date.now();
  private lastTelemetryTimestampMs: number = Date.now();
  private maxStaleTelemetrySec: number = 10;
  private isSafeIslandMode: boolean = false;
  private isReadOnlyFallback: boolean = false;

  public pingHeartbeat(): void {
    this.lastHeartbeatMs = Date.now();
  }

  public updateTelemetryTimestamp(timestampMs: number = Date.now()): void {
    this.lastTelemetryTimestampMs = timestampMs;
    this.checkHealth();
  }

  public checkHealth(): {
    isHealthy: boolean;
    mode: "NORMAL_SYNC" | "SAFE_FALLBACK_ISLAND" | "READ_ONLY_FALLBACK";
    staleSeconds: number;
    error?: string;
  } {
    const now = Date.now();
    const staleTelemetrySec = (now - this.lastTelemetryTimestampMs) / 1000;
    const staleHeartbeatSec = (now - this.lastHeartbeatMs) / 1000;

    // Stale telemetry lockout (> 10s)
    if (staleTelemetrySec > this.maxStaleTelemetrySec) {
      this.isReadOnlyFallback = true;
      return {
        isHealthy: false,
        mode: "READ_ONLY_FALLBACK",
        staleSeconds: Number(staleTelemetrySec.toFixed(1)),
        error: `CRITICAL SCADA ALERT: Telemetry is stale (${staleTelemetrySec.toFixed(1)}s > ${this.maxStaleTelemetrySec}s). Automated dispatch locked out. Operating in Read-Only Fallback mode.`,
      };
    }

    // Heartbeat loss
    if (staleHeartbeatSec > this.maxStaleTelemetrySec) {
      this.isSafeIslandMode = true;
      return {
        isHealthy: false,
        mode: "SAFE_FALLBACK_ISLAND",
        staleSeconds: Number(staleHeartbeatSec.toFixed(1)),
        error: `COMMUNICATION LOSS: Heartbeat timeout (${staleHeartbeatSec.toFixed(1)}s). Switched to Safe Island mode.`,
      };
    }

    this.isReadOnlyFallback = false;
    this.isSafeIslandMode = false;
    return { isHealthy: true, mode: "NORMAL_SYNC", staleSeconds: 0 };
  }

  public canDispatch(): { allowed: boolean; reason?: string } {
    const health = this.checkHealth();
    if (!health.isHealthy) {
      return {
        allowed: false,
        reason: health.error || "SCADA Watchdog failure: Automated dispatch blocked.",
      };
    }
    return { allowed: true };
  }
}

export const scadaWatchdog = new ScadaWatchdogMonitor();

// ============================================================================
// INDUSTRIAL COMMISSIONING SAFETY GATE & PHYSICAL ACTUATION CONTROLLER
// ============================================================================

export interface EngineeringSignoff {
  milestoneId: string;
  engineerName: string;
  professionalLicenseId: string;
  certifyingAuthority: string;
  timestampISO: string;
  digitalSignatureSha256: string;
  certificateFingerprint: string;
}

export class IndustrialSafetyCommissioningGate {
  private milestones: Map<string, SiteValidationMilestone> = new Map();
  private signoffs: Map<string, EngineeringSignoff> = new Map();

  constructor() {
    for (const m of SITE_SAFETY_VALIDATION.checklist) {
      this.milestones.set(m.id, { ...m });
    }
  }

  public recordEngineeringSignoff(
    milestoneId: string,
    engineerName: string,
    professionalLicenseId: string,
    certifyingAuthority: string,
    certificateSecret: string,
  ): { success: boolean; signature: string } {
    if (!this.milestones.has(milestoneId)) {
      throw new Error(`Invalid milestone ID: ${milestoneId}`);
    }

    const timestampISO = new Date().toISOString();
    const signaturePayload = `${milestoneId}|${engineerName}|${professionalLicenseId}|${certifyingAuthority}|${timestampISO}|${certificateSecret}`;
    const digitalSignatureSha256 = sha256(signaturePayload);
    const certificateFingerprint = sha256(
      `FINGERPRINT:${professionalLicenseId}:${certifyingAuthority}`,
    );

    const signoff: EngineeringSignoff = {
      milestoneId,
      engineerName,
      professionalLicenseId,
      certifyingAuthority,
      timestampISO,
      digitalSignatureSha256,
      certificateFingerprint,
    };

    this.signoffs.set(milestoneId, signoff);
    return { success: true, signature: digitalSignatureSha256 };
  }

  public getSignedCount(): number {
    return this.signoffs.size;
  }

  public getTotalMilestonesCount(): number {
    return this.milestones.size;
  }

  public isCommissioningComplete(): boolean {
    return this.signoffs.size === this.milestones.size && this.milestones.size > 0;
  }

  public getSignoff(milestoneId: string): EngineeringSignoff | undefined {
    return this.signoffs.get(milestoneId);
  }

  public clearSignoffs(): void {
    this.signoffs.clear();
  }
}

export const industrialCommissioningGate = new IndustrialSafetyCommissioningGate();

export interface ActuationRequest {
  equipmentId: string;
  equipmentType: "BESS_INVERTER" | "CAPTIVE_GOVERNOR" | "DIESEL_GENSET" | "GRID_BREAKER_132KV";
  targetSetpointMW: number;
  operatorId: string;
  interlockPermissiveKeysEngaged?: boolean;
}

export interface ActuationResult {
  accepted: boolean;
  blockedReason?: string | undefined;
  executionMode: "PHYSICAL_ACTUATION_LOCKED" | "SIMULATION_TWIN_ONLY" | "AUTHORIZED_COMMISSIONED";
  auditHash: string;
}

export class IndustrialActuationController {
  private isCastellKeyPermissiveEngaged: boolean = false;

  public setCastellKeyPermissive(engaged: boolean): void {
    this.isCastellKeyPermissiveEngaged = engaged;
  }

  public requestActuation(request: ActuationRequest): ActuationResult {
    const timestamp = new Date().toISOString();
    const auditPayload = `ACTUATION_REQ|${request.equipmentId}|${request.targetSetpointMW}|${request.operatorId}|${timestamp}`;
    const auditHash = sha256(auditPayload);

    // Rule 1: Equipment actuation must remain disabled by default in simulation / pre-commissioning
    if (!SITE_SAFETY_VALIDATION.isPhysicalActuationPermitted) {
      return {
        accepted: false,
        blockedReason:
          "PHYSICAL ACTUATION PROHIBITED: Closed-loop hardware actuation is permanently locked in simulation mode. Plant engineering has not certified site commissioning milestones (VAL-TEL-01 to VAL-COM-05).",
        executionMode: "PHYSICAL_ACTUATION_LOCKED",
        auditHash,
      };
    }

    // Rule 2: All 6 commissioning milestones must be cryptographically signed
    if (!industrialCommissioningGate.isCommissioningComplete()) {
      return {
        accepted: false,
        blockedReason: `COMMISSIONING INCOMPLETE: Only ${industrialCommissioningGate.getSignedCount()}/${industrialCommissioningGate.getTotalMilestonesCount()} site validation milestones signed off.`,
        executionMode: "PHYSICAL_ACTUATION_LOCKED",
        auditHash,
      };
    }

    // Rule 3: Hardwired trapped-key (Castell) permissive must be engaged
    if (!this.isCastellKeyPermissiveEngaged && !request.interlockPermissiveKeysEngaged) {
      return {
        accepted: false,
        blockedReason:
          "HARDWIRED PERMISSIVE TRIP: Trapped-key (Castell) physical permissive switch is disengaged.",
        executionMode: "PHYSICAL_ACTUATION_LOCKED",
        auditHash,
      };
    }

    // Rule 4: Watchdog health
    const watchdogStatus = scadaWatchdog.canDispatch();
    if (!watchdogStatus.allowed) {
      return {
        accepted: false,
        blockedReason: watchdogStatus.reason,
        executionMode: "PHYSICAL_ACTUATION_LOCKED",
        auditHash,
      };
    }

    return {
      accepted: true,
      executionMode: "AUTHORIZED_COMMISSIONED",
      auditHash,
    };
  }
}

export const industrialActuationController = new IndustrialActuationController();
